function portraitEvidence(sources){var evidence=el('p','helper','À l’origine de cette piste : ');sources.forEach(function(source,index){var id=String(typeof source==='object'?source.source_id||source.id:source),kind=id.split(':')[0],key=id.includes(':')?id.slice(id.indexOf(':')+1):id;var article=(state.examples||[]).find(function(item){return item.id===key})||state.likes.find(function(item){return item.article_id===key});var names={profile:'Portrait déclaré',self_profile:'Portrait déclaré',person:'Relation décrite',event:'Événement raconté',memory:'Votre correction',feedback:'Votre retour de lecture',story:'Votre retour de lecture'};var link=el('a','',names[kind]||article&&article.title||'Lecture aimée');if(kind==='feedback'||kind==='story')link.href='/mon-personnage/?story='+encodeURIComponent(key);else if(kind==='person'||kind==='event')link.href=kind==='person'?'/mes-proches/':'/ma-ligne-de-vie/';else if(kind==='self_profile'||kind==='profile')link.href='/mon-portrait/#self-profile';else if(kind==='memory')link.href='/mon-portrait/#correction-form';else link.href='/mon-portrait/?article='+encodeURIComponent(key)+'#mes-articles';evidence.append(link,document.createTextNode(index<sources.length-1?' ; ':''))});return evidence}
